    const liveBookOrderIds = [...book.bids, ...book.asks].filter((o) => o.clientOrderId && o.clientOrderId.startsWith(botPrefix) || cfg?.activeOrderIds && cfg.activeOrderIds.includes(o.id)).map((o) => o.id);
