    const r1 = 2 * pivot - prev.low;
    const s1 = 2 * pivot - prev.high;
    const r2 = pivot + (prev.high - prev.low);
    const s2 = pivot - (prev.high - prev.low);
    const r3 = prev.high + 2 * (pivot - prev.low);
    const s3 = prev.low - 2 * (prev.high - pivot);
